1	use std::sync::atomic::{AtomicU64, Ordering};
2	use std::sync::{Arc, OnceLock};
3	use std::time::Duration;
4	
5	use dashmap::DashMap;
6	use tokio::process::{ChildStdin, ChildStdout};
7	use tokio::sync::{mpsc, oneshot, Mutex as AsyncMutex, Notify};
8	use tokio_stream::StreamExt;
9	use tokio_util::codec::FramedRead;
10	
11	use crate::error::TscClientError;
12	use crate::protocol::{self, IncomingMessage, Notification, RequestId, RequestMessage};
13	use crate::transport::{self, ContentLengthDecoder};
14	
15	/// Whole frames queued for the writer task. Bounds memory when the child stops reading stdin: past this, callers wait
16	/// in `request()` under their own deadline instead of buffering without limit.
17	const WRITE_QUEUE_FRAMES: usize = 16;
18	
19	type PendingSender = oneshot::Sender<Result<TaggedResponse, TscClientError>>;
20	
21	/// A response's decoded `result`, tagged with the wire-arrival order it was read in —
22	/// see the module doc on [`Client::request`] for why that matters.
23	#[derive(Debug, Clone)]
24	pub struct TaggedResponse {
25	    pub value: serde_json::Value,
26	    pub seq: u64,
27	}
28	
29	/// State shared with the reader and writer tasks. Kept apart from [`ClientInner`] so the tasks never hold the write
30	/// queue's `Sender`: when the last `Client` clone drops the queue closes and the writer releases stdin.
31	struct Shared {
32	    pending: DashMap<u64, PendingSender>,
33	    /// Wire-arrival order, stamped by the reader task as each frame is decoded — not
34	    /// issue order, not wall clock. Lets a caller mechanically check whether a query's
35	    /// answer could reflect an update it already saw acknowledged
36	    /// (`answer.seq > update_ack.seq`), the concrete slice of freshness tracking this
37	    /// crate can build without the real (still-churning) `updateSnapshot` wire shape.
38	    next_seq: AtomicU64,
39	    /// Why the session ended. Set once; the first closer wins.
40	    closed: OnceLock<TscClientError>,
41	    /// Wakes the writer so it drops `ChildStdin` even mid-write and while `Client` clones are alive.
42	    stop_writer: Notify,
43	}
44	
45	impl Shared {
46	    fn close(&self, reason: TscClientError) {
47	        if self.closed.set(reason.clone()).is_err() {
48	            return;
49	        }
50	        self.stop_writer.notify_one();
51	        self.fail_all_pending(&reason);
52	    }
53	
54	    fn dispatch(&self, body: &[u8], seq: u64, notif_tx: &mpsc::UnboundedSender<Notification>) {
55	        match protocol::parse_incoming(body) {
56	            Ok(IncomingMessage::Response(response)) => {
57	                if let Some((_, tx)) = self.pending.remove(&response.id.0) {
58	                    let result = if let Some(error) = response.error {
59	                        Err(TscClientError::RpcError { code: error.code, message: error.message, data: error.data })
60	                    } else {
61	                        Ok(TaggedResponse { value: response.result.unwrap_or(serde_json::Value::Null), seq })
62	                    };
63	                    // A dropped receiver means the caller already gave up (e.g. timed
64	                    // out) — nothing left to deliver to.
65	                    let _ = tx.send(result);
66	                }
67	            }
68	            Ok(IncomingMessage::Notification(notification)) => {
69	                let _ = notif_tx.send(Notification { method: notification.method, params: notification.params });
70	            }
71	            Err(source) => {
72	                // A malformed *body* doesn't desync the stream — the declared
73	                // Content-Length was honored — so the session stays alive; this one
74	                // frame is just unusable.
75	                tracing::warn!("dropping unparsable tsc frame: {source}");
76	            }
77	        }
78	    }
79	
80	    /// Delivers the session-ending failure to every caller still waiting on a response.
81	    /// `TscClientError` is cheaply `Clone`, so every waiter gets its own full copy.
82	    fn fail_all_pending(&self, err: &TscClientError) {
83	        let ids: Vec<u64> = self.pending.iter().map(|entry| *entry.key()).collect();
84	        for id in ids {
85	            if let Some((_, tx)) = self.pending.remove(&id) {
86	                let _ = tx.send(Err(err.clone()));
87	            }
88	        }
89	    }
90	}
91	
92	struct ClientInner {
93	    shared: Arc<Shared>,
94	    /// The only path from a caller to the child's stdin: whole request bodies for the writer task.
95	    write_tx: mpsc::Sender<Vec<u8>>,
96	    next_id: AtomicU64,
97	    notifications: AsyncMutex<Option<mpsc::UnboundedReceiver<Notification>>>,
98	}
99	
100	/// Removes a request's pending entry on every exit path, including a dropped future.
101	struct PendingEntry<'a> {
102	    pending: &'a DashMap<u64, PendingSender>,
103	    id: u64,
104	}
105	
106	impl Drop for PendingEntry<'_> {
107	    fn drop(&mut self) {
108	        self.pending.remove(&self.id);
109	    }
110	}
111	
112	/// Sole owner of `ChildStdin`. Writes one whole frame per queued body, so a request future dropped mid-flight can
113	/// never leave a partial frame on the pipe.
114	async fn write_loop(mut stdin: ChildStdin, mut frames: mpsc::Receiver<Vec<u8>>, shared: Arc<Shared>) {
115	    loop {
116	        let body = tokio::select! {
117	            () = shared.stop_writer.notified() => return,
118	            body = frames.recv() => match body {
119	                Some(body) => body,
120	                None => return,
121	            },
122	        };
123	        tokio::select! {
124	            () = shared.stop_writer.notified() => return,
125	            result = transport::write_frame(&mut stdin, &body) => {
126	                if let Err(source) = result {
127	                    shared.close(TscClientError::Write(Arc::new(source)));
128	                    return;
129	                }
130	            }
131	        }
132	    }
133	}
134	
135	async fn read_loop(
136	    stdout: ChildStdout,
137	    max_frame_bytes: usize,
