52	    let reason_at = |reason: String| TscClientError::VersionCheckFailed { path: tsc_path.to_owned(), reason };
53	
54	    let Some(package_json) =
55	        tsc_path.parent().and_then(|bin_dir| bin_dir.parent()).map(|pkg_dir| pkg_dir.join("package.json"))
56	    else {
57	        return Err(reason_at("tsc_path has no grandparent directory to find package.json in".to_string()));
58	    };
