94	    let mut command = Command::new(config.tsc_path.as_std_path());
95	    command.arg("--api").arg("--async").arg("--cwd").arg(config.cwd.as_std_path());
96	    command.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
97	    command.envs(config.extra_env.iter().map(|(k, v)| (k.as_str(), v.as_str())));
98	    // Best-effort fallback if `Supervisor::shutdown` is never called — this alone
99	    // doesn't guarantee reaping (Drop can't await), only `.shutdown()` does.
100	    command.kill_on_drop(true);
101	
102	    let mut child = command
103	        .spawn()
104	        .map_err(|source| TscClientError::SpawnFailed { path: config.tsc_path.clone(), source: Arc::new(source) })?;
