119	    child: Child,
120	    client: Client,
121	    config: SupervisorConfig,
122	    restart_attempts: Vec<Instant>,
123	    /// Set once a restart-storm cap is hit. Terminal — every later call short-circuits
124	    /// without touching the process again.
125	    failed: bool,
126	}
