129	    pub async fn spawn(config: SupervisorConfig) -> Result<Self, TscClientError> {
130	        let (child, client) = spawn_process(&config).await?;
131	        Ok(Self { child, client, config, restart_attempts: Vec::new(), failed: false })
132	    }
