134	    /// The current session's low-level handle. Cheap to clone. A clone obtained before a
135	    /// supervisor-driven restart fails immediately with the reason its session closed with
136	    /// (`Crashed`, `Write`, `Read`, `MalformedFrame` or `OversizedFrame`) — call this again to get the live one. A
137	    /// clone held across [`Supervisor::shutdown`] fails with `SessionClosed`.
138	    pub fn client(&self) -> Client {
139	        self.client.clone()
140	    }
