142	    /// True while the current session is open and the supervisor hasn't permanently failed. A crash between calls
143	    /// to this method and the next `request()` is still possible — this is a snapshot, not a guarantee.
144	    pub fn is_alive(&self) -> bool {
145	        self.client.closed().is_none() && !self.failed
