148	    /// Sends a request through the current session. A session that ended before the call is restarted first
149	    /// (budget permitting); one that ends during the call is restarted and the call retried once. At most one
150	    /// restart per call, so a request lost to a crash is never silently replayed more than once. A `Timeout` on a
151	    /// live session restarts nothing.
152	    pub async fn request(
153	        &mut self,
154	        method: &str,
155	        params: serde_json::Value,
156	        deadline: Duration,
157	    ) -> Result<TaggedResponse, TscClientError> {
158	        if self.failed {
