//! Shared helper for the Lifecycle-gate integration tests: builds a `SupervisorConfig`
//! pointing at a fresh copy of the `fake-tsc` binary inside a `node_modules/typescript/
//! bin/` layout, so `check_version`'s `package.json` lookup finds a real, matching
//! version rather than needing every test to fake that out itself.
//!
//! Each `tests/*.rs` file compiles this module separately as its own crate, so a
//! helper unused by one particular test binary is expected, not a real dead-code
//! finding — hence the blanket allow below.
#![allow(dead_code)]

use camino::Utf8PathBuf;
use oxc_react_docgen_tsc_client::SupervisorConfig;

pub const PINNED_VERSION: &str = "7.1.0-test";

/// Returns the temp dir (kept alive for the caller's test duration) and a config ready
/// to `Supervisor::spawn`, with `FAKE_TSC_SCENARIO` set to `scenario`.
pub fn spawn_fake(scenario: &str) -> (tempfile::TempDir, SupervisorConfig) {
    let dir = tempfile::tempdir().expect("create temp dir for fake-tsc layout");
    let (tsc_path, cwd) = layout_with_version(&dir, PINNED_VERSION);
    let mut config = SupervisorConfig::new(tsc_path, cwd, &[PINNED_VERSION]);
    config.extra_env.push(("FAKE_TSC_SCENARIO".to_string(), scenario.to_string()));
    (dir, config)
}

/// Number of processes the fake has started in `cwd`: one line per spawn in `fake-tsc-spawns.log`.
pub fn spawn_count(cwd: &camino::Utf8Path) -> usize {
    std::fs::read_to_string(cwd.join("fake-tsc-spawns.log")).map_or(0, |contents| contents.lines().count())
}

/// Waits until the fake has logged at least `at_least` spawns, then lets a spawn that should not have happened show
/// up. A child that is slow to start may not have logged yet when a short-deadline request has already returned.
pub async fn settled_spawn_count(cwd: &camino::Utf8Path, at_least: usize) -> usize {
    let give_up = std::time::Instant::now() + std::time::Duration::from_secs(5);
    while spawn_count(cwd) < at_least && std::time::Instant::now() < give_up {
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    tokio::time::sleep(std::time::Duration::from_millis(300)).await;
    spawn_count(cwd)
}

/// Builds the `node_modules/typescript/{package.json,bin/tsc}` layout with the given
/// version string and a copy of the real `fake-tsc` binary at `bin/tsc`. Returns
/// `(tsc_path, cwd)`.
pub fn layout_with_version(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    let bin_dir = typescript_dir.join("bin");
    std::fs::create_dir_all(&bin_dir).expect("create node_modules/typescript/bin");
    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
        .expect("write package.json");

    let fake_tsc_src = std::path::PathBuf::from(env!("CARGO_BIN_EXE_fake-tsc"));
    let tsc_dest = bin_dir.join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
    std::fs::copy(&fake_tsc_src, &tsc_dest).expect("copy fake-tsc binary into place");

    (
        Utf8PathBuf::from_path_buf(tsc_dest).expect("temp path is UTF-8"),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
    )
}

/// Same layout, but without ever placing a binary at `bin/tsc` — for the missing-binary
/// case.
pub fn layout_without_binary(dir: &tempfile::TempDir, version: &str) -> (Utf8PathBuf, Utf8PathBuf) {
    let typescript_dir = dir.path().join("node_modules").join("typescript");
    std::fs::create_dir_all(&typescript_dir).expect("create node_modules/typescript");
    std::fs::write(typescript_dir.join("package.json"), format!(r#"{{"version": "{version}"}}"#))
        .expect("write package.json");
    let tsc_path = typescript_dir.join("bin").join(if cfg!(windows) { "tsc.exe" } else { "tsc" });
    (
        Utf8PathBuf::from_path_buf(tsc_path).expect("temp path is UTF-8"),
        Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).expect("temp path is UTF-8"),
    )
}
mod common;

use std::time::Duration;

use oxc_react_docgen_tsc_client::Supervisor;
use serde_json::json;

#[tokio::test]
async fn dropping_a_request_future_mid_write_never_wedges_the_session() {
    let (_dir, config) = common::spawn_fake("echo");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let client = supervisor.client();

    let big = client.request("big", json!({ "blob": "x".repeat(8 * 1024 * 1024) }), Duration::from_secs(10));
    let elapsed = tokio::time::timeout(Duration::from_millis(1), big).await;
    assert!(elapsed.is_err(), "the 8 MiB request must still be in flight when its future is dropped");

    let ping = client.request("ping", json!({}), Duration::from_secs(2)).await.expect("ping after a dropped request");
    assert_eq!(ping.value["echo"], json!({}));
    assert!(supervisor.is_alive());
}
mod common;

use std::time::{Duration, Instant};

use oxc_react_docgen_tsc_client::{Client, Supervisor, TscClientError};
use serde_json::json;

#[tokio::test]
async fn a_process_that_exits_mid_session_fails_the_next_request_as_crashed() {
    // Answers the first request, then exits — a second request gets no response.
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let mut supervisor = oxc_react_docgen_tsc_client::Supervisor::spawn(config).await.expect("spawn fake tsc");

    let first = supervisor.request("first", serde_json::json!({}), Duration::from_secs(2)).await;
    assert!(first.is_ok(), "expected the first request to succeed, got {first:?}");

    // The second request may report Crashed directly, or (since Supervisor::request
    // auto-restarts once on Crashed) succeed against the restarted process — both are
    // correct; what matters is it isn't left hanging or silently wrong. Use the
    // low-level Client directly instead, which never restarts, to observe the crash
    // itself deterministically.
    let raw_client: Client = supervisor.client();
    // Give the crashed process's reader task a moment to notice EOF.
    tokio::time::sleep(Duration::from_millis(100)).await;
    let second = raw_client.request("second", serde_json::json!({}), Duration::from_secs(2)).await;
    match second {
        // Whether the crash surfaces as `Crashed` (reader task noticed EOF first) or
        // `Write` (the stdin pipe was already closed) is a timing race, not something
        // this crate controls — both mean the same thing: the process is gone.
        Err(TscClientError::Crashed { .. } | TscClientError::Write(_)) => {}
        Err(other) => panic!("expected Crashed or Write, got {other:?}"),
        Ok(response) => panic!("expected an error, got a response: {response:?}"),
    }
}

#[tokio::test]
async fn a_fatal_frame_from_a_live_child_is_restarted_not_timed_out() {
    let (_dir, config) = common::spawn_fake("fatal_frame_once_then_echo");
    let cwd = config.cwd.clone();
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    let first = supervisor.request("ping", json!({ "n": 1 }), Duration::from_secs(2)).await.expect("restarted request");
    assert_eq!(first.value["echo"], json!({ "n": 1 }));
    assert!(supervisor.is_alive());
    assert_eq!(common::spawn_count(&cwd), 2);

    let second = supervisor.request("ping", json!({ "n": 2 }), Duration::from_secs(2)).await.expect("second request");
    assert_eq!(second.value["echo"], json!({ "n": 2 }));
    assert_eq!(common::spawn_count(&cwd), 2);
}

#[tokio::test]
async fn a_child_that_always_sends_a_fatal_frame_consumes_the_restart_budget() {
    let (_dir, config) = common::spawn_fake("fatal_frame_then_alive");
    let cwd = config.cwd.clone();
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    for call in 1..=3 {
        // The deadline is only an upper bound: the frame error returns as soon as the fake writes it, but a loaded
        // machine can take longer than a few hundred ms to start the restarted child.
        let result = supervisor.request("ping", json!({}), Duration::from_secs(5)).await;
        assert!(matches!(result, Err(TscClientError::MalformedFrame { .. })), "call {call}: got {result:?}");
    }
    let fourth = supervisor.request("ping", json!({}), Duration::from_secs(5)).await;
    assert!(matches!(fourth, Err(TscClientError::RestartStormDetected { attempts: 3, .. })), "got {fourth:?}");
    assert_eq!(common::spawn_count(&cwd), 4);
}

#[tokio::test]
async fn a_clone_from_before_a_restart_fails_immediately_with_the_old_sessions_reason() {
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let stale = supervisor.client();

    supervisor.request("first", json!({}), Duration::from_secs(2)).await.expect("first request");
    supervisor
        .request("second", json!({}), Duration::from_secs(2))
        .await
        .expect("second request restarts and succeeds");

    let start = Instant::now();
    let result = stale.request("ping", json!({}), Duration::from_secs(2)).await;
    assert!(start.elapsed() < Duration::from_millis(100), "took {:?}", start.elapsed());
    let Err(TscClientError::Crashed { .. } | TscClientError::Write(_)) = &result else {
        panic!("expected Crashed or Write, got {result:?}");
    };
    let (Err(error), Some(closed)) = (&result, stale.closed()) else { panic!("closed() must be Some") };
    assert_eq!(std::mem::discriminant(error), std::mem::discriminant(&closed));

    // `exit_after:1` means the restarted child has already served its one request, so a raw ping on the current
    // client would race that exit; the supervisor restarts again and answers instead.
    let live = supervisor.request("ping", json!({}), Duration::from_secs(2)).await;
    assert!(live.is_ok(), "the supervisor must still serve requests, got {live:?}");
}

#[tokio::test]
async fn the_first_close_reason_wins() {
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let client = supervisor.client();

    let start = Instant::now();
    let (a, b) = tokio::join!(
        client.request("a", json!({}), Duration::from_secs(2)),
        client.request("b", json!({}), Duration::from_secs(2)),
    );
    assert!(start.elapsed() < Duration::from_secs(1), "took {:?}", start.elapsed());

    let is_crash = |result: &Result<_, TscClientError>| {
        matches!(result, Err(TscClientError::Crashed { .. } | TscClientError::Write(_)))
    };
    assert!(
        (a.is_ok() && is_crash(&b)) || (b.is_ok() && is_crash(&a)),
        "expected exactly one Ok and one Crashed/Write, got a={a:?} b={b:?}"
    );

    let reasons: Vec<_> = (0..3).map(|_| client.closed().map(|reason| std::mem::discriminant(&reason))).collect();
    assert!(reasons[0].is_some());
    assert!(reasons.iter().all(|reason| *reason == reasons[0]));
}
mod common;

use std::time::{Duration, Instant};

use oxc_react_docgen_tsc_client::{Supervisor, TscClientError};
use serde_json::json;

#[tokio::test]
async fn a_request_the_child_never_answers_times_out() {
    let (_dir, config) = common::spawn_fake("never_respond");
    let cwd = config.cwd.clone();
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    let result = supervisor.request("ping", serde_json::json!({}), Duration::from_millis(150)).await;
    match result {
        Err(TscClientError::Timeout { method, after }) => {
            assert_eq!(method, "ping");
            assert_eq!(after, Duration::from_millis(150));
        }
        Err(other) => panic!("expected Timeout, got {other:?}"),
        Ok(response) => panic!("expected Timeout, got a response: {response:?}"),
    }

    // A timeout on a live session is not a restart trigger.
    assert_eq!(common::settled_spawn_count(&cwd, 1).await, 1);

    supervisor.shutdown().await.expect("shutdown");
}

#[tokio::test]
async fn a_child_that_stops_reading_stdin_cannot_hold_a_request_past_its_deadline() {
    let (_dir, config) = common::spawn_fake("never_read");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let client = supervisor.client();

    let deadline = Duration::from_millis(100);
    let timed = |n: usize| {
        let client = client.clone();
        async move {
            let params = json!({ "blob": "x".repeat(1024 * 1024), "n": n });
            let start = Instant::now();
            let result = client.request("big", params, deadline).await;
            (result, start.elapsed())
        }
    };
    // Bounded from outside so a regression fails fast instead of hanging the suite.
    let results = tokio::time::timeout(Duration::from_secs(10), async {
        tokio::join!(timed(0), timed(1), timed(2), timed(3), timed(4), timed(5), timed(6), timed(7))
    })
    .await
    .expect("every request must return on its own deadline");

    let results = [results.0, results.1, results.2, results.3, results.4, results.5, results.6, results.7];
    for (result, elapsed) in results {
        match result {
            Err(TscClientError::Timeout { after, .. }) => assert_eq!(after, deadline),
            other => panic!("expected Timeout, got {other:?}"),
        }
        // Old behavior blocked for seconds or forever; 1s leaves room for a scheduling stall under load.
        assert!(elapsed < Duration::from_secs(1), "request outlived its deadline: {elapsed:?}");
    }

    let start = Instant::now();
    supervisor.shutdown().await.expect("shutdown must succeed while a write is blocked");
    assert!(start.elapsed() < Duration::from_secs(5), "shutdown took {:?}", start.elapsed());
}
mod common;

use std::time::{Duration, Instant};

use oxc_react_docgen_tsc_client::{Supervisor, TscClientError};
use serde_json::json;

#[tokio::test]
async fn shutdown_force_kills_and_reaps_a_process_that_ignores_it() {
    // Survives stdin EOF for far longer than the supervisor's grace period.
    let (_dir, config) = common::spawn_fake("shutdown_slow:30000");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    let start = Instant::now();
    let status = supervisor.shutdown().await.expect("shutdown must force-kill and still succeed, not hang for 30s");
    let elapsed = start.elapsed();

    assert!(!status.success(), "a force-killed process must not report success: {status:?}");
    // The 2s grace period plus kill/reap overhead, well under the fake's 30s stubbornness.
    assert!(elapsed >= Duration::from_secs(2), "expected shutdown to wait out the 2s grace period, took {elapsed:?}");
    assert!(elapsed < Duration::from_secs(10), "expected shutdown to force-kill well before 10s, took {elapsed:?}");
}

#[tokio::test]
async fn shutdown_returns_quickly_when_the_process_exits_promptly() {
    let (_dir, config) = common::spawn_fake("shutdown_slow:0");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    let start = Instant::now();
    supervisor.shutdown().await.expect("shutdown");
    let elapsed = start.elapsed();

    assert!(
        elapsed < Duration::from_secs(2),
        "expected a prompt exit to not wait out the grace period, took {elapsed:?}"
    );
}

#[tokio::test]
async fn shutdown_closes_stdin_while_a_client_clone_is_held() {
    let (_dir, config) = common::spawn_fake("echo");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let _clone = supervisor.client();

    let start = Instant::now();
    let status = supervisor.shutdown().await.expect("shutdown");
    let elapsed = start.elapsed();

    assert!(status.success(), "the child exits cleanly on stdin EOF: {status:?}");
    assert!(elapsed < Duration::from_secs(1), "the grace window must not be consumed, took {elapsed:?}");
}

#[tokio::test]
async fn shutdown_fails_in_flight_requests_on_clones_with_session_closed() {
    let (_dir, config) = common::spawn_fake("never_respond");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let client = supervisor.client();
    let in_flight = tokio::spawn(async move {
        let result = client.request("ping", json!({}), Duration::from_secs(30)).await;
        (result, Instant::now())
    });

    tokio::time::sleep(Duration::from_millis(50)).await;
    let shutdown_started = Instant::now();
    supervisor.shutdown().await.expect("shutdown");

    let (result, failed_at) = in_flight.await.expect("request task");
    assert!(matches!(result, Err(TscClientError::SessionClosed)), "got {result:?}");
    let waited = failed_at.duration_since(shutdown_started);
    assert!(waited < Duration::from_secs(1), "the in-flight request failed {waited:?} after shutdown started");
}

#[tokio::test]
async fn a_clone_held_across_shutdown_reports_session_closed() {
    let (_dir, config) = common::spawn_fake("echo");
    let supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");
    let stale = supervisor.client();
    supervisor.shutdown().await.expect("shutdown");

    assert!(matches!(stale.closed(), Some(TscClientError::SessionClosed)));
    let start = Instant::now();
    let result = stale.request("ping", json!({}), Duration::from_secs(2)).await;
    assert!(matches!(result, Err(TscClientError::SessionClosed)), "got {result:?}");
    assert!(start.elapsed() < Duration::from_millis(100), "took {:?}", start.elapsed());
}

#[tokio::test]
async fn shutdown_returns_the_reaped_exit_status() {
    let (_dir, config) = common::spawn_fake("exit_after:1:7");
    let mut supervisor = Supervisor::spawn(config).await.expect("spawn fake tsc");

    let first = supervisor.request("first", json!({}), Duration::from_secs(2)).await;
    assert!(first.is_ok(), "expected the first request to succeed, got {first:?}");

    tokio::time::sleep(Duration::from_millis(100)).await;
    let status = supervisor.shutdown().await.expect("shutdown");
    assert_eq!(status.code(), Some(7));
}

